test('real smoke and guarding states have visible overlays and descriptive cell labels',()=>{let s=Engine.createState('u03');s=Engine.command(s,{type:'skill',unitId:'scout',skillId:'smoke',x:2,y:3,revision:s.revision}).state;s=Engine.command(s,{type:'skill',unitId:'guardian',skillId:'guard',revision:s.revision}).state;const markup=Renderer.board(s,Missions.getMission('u03'));assert.equal((markup.match(/class="smoke-cloud"/g)||[]).length,s.smoke.length);assert.match(markup,/status-shield/);assert.match(markup,/掩護中，本回合減傷/);assert.match(markup,/煙幕中，本回合阻擋遠程視線/);});
