test('every build, top and bottom choice changes actual SVG geometry or outfit details',()=>{for(const [key,values] of Object.entries({build:['regular','slim','broad'],top:['field','shirt','jacket','vest'],bottom:['straight','cargo','tapered']})){const outputs=values.map(value=>Renderer.avatarSVG('guardian',{[key]:value}));assert.equal(new Set(outputs).size,values.length,key);for(const output of outputs)assert.match(output,/<svg/);}assert.match(Renderer.avatarSVG('guardian',{build:'broad'}),/scale\(1\.13 1\)/);assert.match(Renderer.avatarSVG('guardian',{bottom:'cargo'}),/M30 101h13v10H30/);assert.match(Renderer.avatarSVG('guardian',{top:'jacket'}),/M52 66v29/);});
test('u03 UI action flow wins, saves every accepted operation, and completes learning reflection',async()=>{const {app,nodes}=fixture();app.start('u03');const route=[{type:'move',unitId:'scout',x:2,y:1},{type:'skill',unitId:'scout',skillId:'rescue',targetId:'civilian-1'},{type:'move',unitId:'guardian',x:3,y:3},{type:'skill',unitId:'guardian',skillId:'guard'},{type:'move',unitId:'medic',x:4,y:4},{type:'skill',unitId:'medic',skillId:'guard'},{type:'endTurn'},{type:'move',unitId:'scout',x:0,y:2},{type:'skill',unitId:'scout',skillId:'guard'},{type:'move',unitId:'guardian',x:5,y:3},{type:'skill',unitId:'guardian',skillId:'rescue',targetId:'civilian-2'},{type:'move',unitId:'medic',x:1,y:4},{type:'skill',unitId:'medic',skillId:'guard'},{type:'endTurn'},{type:'skill',unitId:'scout',skillId:'guard'},{type:'move',unitId:'guardian',x:2,y:3},{type:'skill',unitId:'guardian',skillId:'guard'},{type:'move',unitId:'medic',x:0,y:4},{type:'skill',unitId:'medic',skillId:'heal',targetId:'guardian'},{type:'endTurn'},{type:'skill',unitId:'scout',skillId:'guard'},{type:'move',unitId:'guardian',x:0,y:3}];for(const command of route){if(command.unitId)app.selectUnit(command.unitId);app.prepare(command);assert.ok(app.pending,JSON.stringify(command));await app.execute(app.pending.command);assert.equal(app.store.loadSession().data.revision,app.state.revision);}assert.equal(app.state.status,'won');assert.equal(app.state.metrics.rescued,2);assert.equal(app.view,'result');nodes.get('reflection-form').elements={reason:{value:'依能力界線先求助並建立交接。'},revisionCondition:{value:'若接手未確認就調整等待並回報限制。'}};app.finishReflection();assert.equal(app.finished.persisted,true);assert.equal(app.progress.completed.u03.count,1);});
