test('spent move and skill display completed-turn guidance instead of inviting an unavailable skill',async()=>{const {app,nodes}=fixture();app.start('u03');await app.execute({type:'move',unitId:'guardian',x:2,y:2,revision:0});await app.execute({type:'skill',unitId:'guardian',skillId:'guard',revision:1});assert.equal(app.selected.acted,true);assert.equal(app.selected.moved,true);assert.match(nodes.get('app').innerHTML,/本回合行動已完成，選其他隊員或結束回合/);assert.ok(!nodes.get('app').innerHTML.includes('本回合已移動，仍可使用技能'));assert.match(app.actionbar(app.uiData()),/本回合行動已完成/);});
