test('imported audio preferences apply immediately and only verified successful saves clear warnings',()=>{const source=fixture(),target=fixture();source.app.profile.settings.musicEnabled=false;source.app.profile.settings.musicVolume=.1;source.app.saveProfile();target.app.profile.settings.musicEnabled=true;target.app.music.setEnabled(true);target.app.warning='暫存記憶體';target.app.pendingImport=source.app.store.exportJSON();target.app.confirmImport();assert.equal(target.app.music.enabled,false);assert.equal(target.app.music.volume,.1);assert.equal(target.app.warning,'');target.app.persist({ok:true,persisted:false,message:'尚未保存'});assert.equal(target.app.warning,'尚未保存');target.app.persist({ok:true});assert.equal(target.app.warning,'尚未保存');target.app.persist({ok:true,persisted:true});assert.equal(target.app.warning,'');});
test('animation presentation uses old-round panels and suppresses interactive range overlays',async()=>{const {app,nodes}=fixture();app.start('u03');app.profile.settings.reducedMotion=false;const pending=app.execute({type:'endTurn',revision:0});assert.equal(app.state.round,2);assert.equal(app.visualState.round,1);app.visualState.units[0].hp=7;app.render();const html=nodes.get('app').innerHTML;assert.match(html,/回合 <strong>1<\/strong>/);assert.match(html,/<small>7\/18<\/small>/);assert.match(html,/生命 7\/18/);assert.ok(!/class="tile[^"]* reachable/.test(html));assert.ok(!/class="tile[^"]* targetable/.test(html));assert.match(html,/正在回放已確認的行動/);assert.ok(!app.actionbar(app.uiData()).includes('本回合行動已完成'));app.interruptAnimation();assert.equal(app.presentationSummary,null);assert.match(nodes.get('app').innerHTML,/回合 <strong>2<\/strong>/);await new Promise(resolve=>setTimeout(resolve,15));await pending;});
test('editing an individual outfit control updates both the preview and the selected art-mode button',()=>{const {app,nodes}=fixture();app.wardrobe('guardian');const original=new Element('button'),custom=new Element('button');original.dataset.artmode='illustrated';custom.dataset.artmode='custom';nodes.get('game-dialog').querySelectorAll=selector=>selector==='[data-artmode]'?[original,custom]:[];app.change({target:{dataset:{appearance:'top'},value:'jacket'}});assert.equal(original.attributes['aria-pressed'],'false');assert.equal(custom.attributes['aria-pressed'],'true');assert.equal(custom.className,'button primary');assert.match(nodes.get('wardrobe-preview').innerHTML,/自由造型/);});
test('each enemy has a compact current intent label that obeys the shared preview toggle',()=>{let state=Engine.createState('u03');state=Engine.command(state,{type:'move',unitId:'scout',x:5,y:3,revision:0}).state;const intents=Engine.enemyIntents(state),mission=Missions.getMission('u03');const shown=Renderer.board(state,mission,{intents,showIntents:true});assert.equal((shown.match(/class="enemy-intent /g)||[]).length,intents.length);assert.match(shown,/敵方階段預告/);for(const intent of intents.filter(i=>i.type==='attack'))assert.ok(shown.includes('−'+intent.damage));const hidden=Renderer.board(state,mission,{intents,showIntents:false});assert.ok(!hidden.includes('class="enemy-intent '));assert.ok(!hidden.includes('敵方階段預告'));});
test('coach advice and frozen-command preview never execute a move without the player confirming',async()=>{const {app,nodes}=fixture();app.start('u03');app.coach();assert.equal(app.state.revision,0);assert.match(nodes.get('game-dialog').innerHTML,/推薦|提示/);assert.match(nodes.get('game-dialog').innerHTML,/預覽建議/);assert.match(nodes.get('game-dialog').innerHTML,/不是唯一解/);app.previewCoach();assert.equal(app.state.revision,0);assert.ok(app.pending);assert.equal(app.pending.command.unitId,'scout');assert.equal(app.pending.command.revision,0);await app.execute(app.pending.command);assert.equal(app.state.revision,1);});
