test('recommended endTurn still asks before leaving unused teammate actions',()=>{const {app,nodes}=fixture();app.start('u03');app.prepare({type:'endTurn',revision:0});assert.match(app.actionbar(app.uiData()),/結束回合/);const control={disabled:false,dataset:{action:'confirm-action'}};app.click({target:{closest:selector=>selector==='[data-action]'?control:null}});assert.equal(app.state.round,1);assert.match(nodes.get('game-dialog').innerHTML,/確認結束回合/);});
test('reflection draft survives a new app instance and never counts as completed learning',()=>{const {app,context}=fixture();terminal(app);app.reflection={reason:'我會先核對教材中的能力界線。',revisionCondition:'如果督導無法接手，會調整等待與回報。'};app.scheduleDraft();assert.equal(app.flushDraft().persisted,true);assert.equal(app.store.loadProgress().data.completed.u03,undefined);const reloaded=new context.TacticalGameApp.App();reloaded.continue();assert.equal(reloaded.view,'result');assert.equal(reloaded.reflection.reason,'我會先核對教材中的能力界線。');assert.match(reloaded.draftStatus,/已恢復/);assert.equal(reloaded.finished,null);});
test('draft debounce ignores a superseded callback and saves only the latest captured text',()=>{const {app}=fixture();terminal(app);app.reflection={reason:'第一版',revisionCondition:''};app.scheduleDraft();const old=app.pendingDraft;app.reflection.reason='修訂版';app.scheduleDraft();const latest=app.pendingDraft;assert.equal(app.flushDraft(old).skipped,true);assert.equal(app.pendingDraft,latest);assert.equal(app.store.loadSession().draft.reason,'');assert.equal(app.flushDraft(latest).persisted,true);assert.equal(app.store.loadSession().draft.reason,'修訂版');});
test('starting a fresh attempt flushes old reflection to its archive and rejects a delayed callback',()=>{const {app}=fixture();terminal(app);app.reflection={reason:'舊局尚未完成的理由',revisionCondition:''};app.scheduleDraft();const delayed=app.pendingDraft,oldId=app.reflectionAttemptId;app.start('u01');assert.notEqual(app.reflectionAttemptId,oldId);assert.equal(app.store.loadAttempts().data.at(-1).draft.reason,'舊局尚未完成的理由');assert.equal(app.store.loadAttempts().data.at(-1).learning,null);assert.equal(app.flushDraft(delayed).skipped,true);assert.equal(app.store.loadSession().draft.reason,'');});
test('visibility pause and export flush the current draft before reading the backup',()=>{const {app,document,listeners}=fixture();terminal(app);app.reflection={reason:'切換分頁前的內容',revisionCondition:''};app.scheduleDraft();document.hidden=true;for(const fn of listeners.visibilitychange)fn();assert.equal(app.store.loadSession().draft.reason,'切換分頁前的內容');document.hidden=false;app.reflection.reason='下載前的最新內容';app.scheduleDraft();let downloaded='';app.download=text=>{downloaded=text;};app.export();assert.equal(JSON.parse(downloaded).session.draft.reason,'下載前的最新內容');});
test('imported terminal draft restores its own text and an old pending callback cannot overwrite it',()=>{const from=fixture(),to=fixture();terminal(from.app);from.app.reflection={reason:'匯入檔案自己的理由',revisionCondition:'匯入檔案自己的條件'};from.app.scheduleDraft();from.app.flushDraft();terminal(to.app);to.app.reflection={reason:'不可串入的舊文字',revisionCondition:''};to.app.scheduleDraft();const stale=to.app.pendingDraft;to.app.pendingImport=from.app.store.exportJSON();to.app.confirmImport();to.app.continue();assert.equal(to.app.reflection.reason,'匯入檔案自己的理由');assert.equal(to.app.flushDraft(stale).skipped,true);assert.equal(to.app.store.loadSession().draft.reason,'匯入檔案自己的理由');});
test('storage failure retains the newest draft in an export and clearly reports memory-only status',()=>{const {app}=fixture({failSave:true});terminal(app);app.reflection={reason:'暫存仍須保留',revisionCondition:'看到新資訊再修正'};app.scheduleDraft();const result=app.flushDraft();assert.equal(result.ok,true);assert.equal(result.persisted,false);assert.match(app.draftStatus,/暫留本頁記憶體/);assert.equal(JSON.parse(app.store.exportJSON()).session.draft.reason,'暫存仍須保留');});
test('briefing preloads only the current three illustrated pose sets without blocking or duplication',()=>{const {app,context}=fixture(),images=[];context.Image=class{constructor(){images.push(this);}set src(value){this.url=value;}};app.briefing('u03');assert.equal(images.length,15);assert.ok(images.every(i=>/-(move|attack|hit|heal|rescue)\.png$/.test(i.url)));assert.ok(images.every(i=>!i.url.includes('-alt-')));assert.equal(app.state,null);app.briefing('u03');assert.equal(images.length,15);assert.equal(app.preloadedPosePaths.size,15);for(const img of images)img.onload();assert.equal(app.preloadImages.size,0);});
