test('u06 briefing accurately teaches cumulative holding without requiring rotation or interaction',()=>{const {app,nodes}=fixture();const before=JSON.stringify(Missions.missions);app.briefing('u06');const html=nodes.get('game-dialog').innerHTML;assert.match(html,/累計完成 3 次守點/);assert.match(html,/同一人可持續守點/);assert.match(html,/不需要使用「任務互動」/);assert.ok(!html.includes('輪流占住標記格'));assert.ok(!html.includes('不要讓同一人連續承擔'));assert.equal(JSON.stringify(Missions.missions),before);});
test('occupied u06 hold nodes keep their true 1/3 progress visible in the panel, map and mobile summary',async()=>{const {app,nodes}=fixture();app.start('u06');const route=[{type:'move',unitId:'scout',x:3,y:1},{type:'skill',unitId:'scout',skillId:'guard'},{type:'move',unitId:'guardian',x:2,y:4},{type:'skill',unitId:'guardian',skillId:'guard'},{type:'move',unitId:'medic',x:3,y:5},{type:'skill',unitId:'medic',skillId:'guard'},{type:'endTurn'}];for(const command of route)await app.execute(command);assert.equal(app.state.round,2);assert.ok(app.state.objects.every(o=>o.progress===1));const html=nodes.get('app').innerHTML;assert.match(html,/data-node-id="north"/);assert.match(html,/data-node-id="south"/);assert.match(html,/站此格至回合結束，累計守點/);assert.match(app.nodeProgress(app.state,true),/北側輪值點 <b>1\/3<\/b>/);const board=Renderer.board(app.state,app.mission);assert.match(board,/任務點 北側輪值點，進度 1\/3/);assert.match(board,/任務點 南側輪值點，進度 1\/3/);assert.equal((board.match(/class="node-progress-badge /g)||[]).length,2);assert.equal(app.store.Engine.validateState(app.state).ok,true);});
test('u10 exposes dependencies, completed nodes and the genuine half-finished 1/2 handover',async()=>{const {app}=fixture();app.start('u10');assert.match(app.nodeProgress(app.state),/先完成：①來源與時點/);assert.match(app.nodeProgress(app.state),/先完成：②效力核對/);const route=[{type:'move',unitId:'scout',x:1,y:1},{type:'skill',unitId:'scout',skillId:'guard'},{type:'move',unitId:'guardian',x:2,y:1},{type:'skill',unitId:'guardian',skillId:'interact',targetId:'date'},{type:'move',unitId:'medic',x:2,y:2},{type:'skill',unitId:'medic',skillId:'guard'},{type:'endTurn'},{type:'move',unitId:'scout',x:3,y:1},{type:'skill',unitId:'scout',skillId:'guard'},{type:'move',unitId:'guardian',x:1,y:3},{type:'skill',unitId:'guardian',skillId:'guard'},{type:'move',unitId:'medic',x:5,y:2},{type:'skill',unitId:'medic',skillId:'interact',targetId:'effect'},{type:'endTurn'},{type:'move',unitId:'scout',x:5,y:3},{type:'skill',unitId:'scout',skillId:'shot',targetId:'enemy-2'},{type:'move',unitId:'guardian',x:2,y:5},{type:'skill',unitId:'guardian',skillId:'guard'},{type:'move',unitId:'medic',x:7,y:3},{type:'skill',unitId:'medic',skillId:'heal',targetId:'medic'},{type:'endTurn'},{type:'move',unitId:'scout',x:6,y:5},{type:'skill',unitId:'scout',skillId:'guard'},{type:'move',unitId:'guardian',x:4,y:6},{type:'skill',unitId:'guardian',skillId:'guard'},{type:'move',unitId:'medic',x:8,y:4},{type:'skill',unitId:'medic',skillId:'interact',targetId:'advice'}];for(const command of route)await app.execute(command);assert.equal(app.state.objects.find(o=>o.id==='advice').progress,1);const panel=app.nodeProgress(app.state);assert.match(panel,/③諮詢交接/);assert.match(panel,/I6 · <b>1\/2<\/b>/);assert.ok(!panel.includes('先完成：②效力核對'));const board=Renderer.board(app.state,app.mission);assert.match(board,/任務點 ①來源與時點，進度 1\/1，已完成/);assert.match(board,/任務點 ③諮詢交接，進度 1\/2/);assert.equal(app.store.Engine.validateState(app.state).ok,true);});
test('all no-civilian chapters use node or hold facts rather than claiming a completed rescue',async()=>{const {app}=fixture();for(const mission of Missions.missions.filter(m=>m.civilians.length===0)){app.start(mission.id);while(app.state.status==='active')await app.execute({type:'endTurn'});const html=app.result();assert.ok(!html.includes('救援任務已交接'),mission.id);assert.ok(!html.includes('<span>完成護送</span>'),mission.id);assert.match(html,/<span>完成節點<\/span>/);if(mission.id==='u06'){assert.match(html,/北側輪值點 0\/3/);assert.match(html,/南側輪值點 0\/3/);assert.ok(!html.includes('累計守點完成，'));}else assert.match(html,/演訓節點完成 0\//);assert.match(html,/責任仍/);}});
