test('battle view activates the phone-only reserved dock space and clears it on other screens',()=>{const {app,nodes}=fixture();app.start('u03');assert.equal(nodes.get('app').attributes['data-view'],'battle');app.navigate('home');assert.equal(nodes.get('app').attributes['data-view'],'home');const css=fs.readFileSync('css/tactical.css','utf8');assert.match(css,/@media\(max-width:680px\)\{\s*#app\[data-view="battle"\]\{padding-bottom:calc\(252px \+ env\(safe-area-inset-bottom,0px\)\)/);});
test('phone dock uses the existing controls once, with safe-area confirmation, end-turn and 44px targets',()=>{const {app,nodes}=fixture();app.start('u03');const target=app.store.Engine.reachable(app.state,'guardian')[0];app.prepare({type:'move',unitId:'guardian',x:target.x,y:target.y});const html=nodes.get('app').innerHTML;assert.equal((html.match(/data-action="confirm-action"/g)||[]).length,1);assert.equal((html.match(/data-action="cancel-action"/g)||[]).length,1);assert.equal((html.match(/data-action="end-turn"/g)||[]).length,1);const css=fs.readFileSync('css/tactical.css','utf8');assert.match(css,/\.battle-sidebar\.right \.end-turn\{position:fixed;[^}]+bottom:calc\(8px \+ env\(safe-area-inset-bottom,0px\)\)[^}]+min-height:44px/);assert.match(css,/\.battle-actionbar\{position:fixed;[^}]+bottom:calc\(8px \+ env\(safe-area-inset-bottom,0px\)\)/);assert.match(css,/grid-template-columns:repeat\(6,minmax\(44px,1fr\)\)/);assert.match(css,/\.battle-actionbar \.actionbar-copy\{position:fixed;[^}]+max-height:76px;overflow-y:auto/);assert.match(css,/min-width:calc\(var\(--cols\)\*44px \+ 2px\)/);});
test('chapter-card span containers are block-level with clipped, explicitly sized image regions',()=>{const css=fs.readFileSync('css/tactical.css','utf8');assert.match(css,/\.mission-card-art\{display:block;height:99px;[^}]*position:relative;overflow:hidden/);assert.match(css,/\.mission-card-body\{display:block;padding:/);assert.match(css,/\.mission-card-art \.campus-art\{display:block;position:absolute;inset:0;height:100%;width:100%;object-fit:cover/);assert.match(css,/\.chapter-library \.mission-card-art\{height:110px/);assert.match(css,/\.mission-card-art\{height:100%;min-height:114px/);const {app}=fixture();for(const mission of Missions.missions){const card=app.missionCard(mission);assert.ok(card.includes(mission.title));assert.match(card,/class="mission-card-number"/);assert.match(card,/class="mission-card-body"/);}});

test('chapter-card images use top-aligned full-size crops without legacy translation on either layout',()=>{const css=fs.readFileSync('css/tactical.css','utf8');const imageRules=Array.from(css.matchAll(/\.mission-card-art \.campus-art\{([^}]+)\}/g),m=>m[1]);assert.ok(imageRules.length>=2);for(const rule of imageRules){assert.match(rule,/height:100%/);assert.match(rule,/width:100%/);assert.match(rule,/transform:none/);assert.match(rule,/object-position:center top/);assert.ok(!rule.includes('150%'));assert.ok(!rule.includes('translate'));}});

function classroomFixture(extra={}){const calls=[],api={openPanel(){calls.push({type:'open'});},capture(){calls.push({type:'capture',missionId:api.store?.loadSession().data?.missionId||null});},resetConsent(reason){calls.push({type:'reset',reason});}},runtimeConfig={mode:'formal',legacyUrl:'/legacy-v1/',attendanceUrl:'/legacy-v1/#classroom-receipt'};const classroomClient={mountPublic(document,host,config,store){calls.push({type:'mount',document,host,config,key:store.key});api.store=store;return api;}};const f=fixture({runtimeConfig,classroomConfig:{enabled:true},classroomClient,...extra});return {...f,calls,api};}
test('runtime defaults to isolated preview and never mounts or captures a classroom client',()=>{let mounted=0,captured=0;const f=fixture({classroomConfig:{enabled:true},classroomClient:{mountPublic(){mounted++;return {capture(){captured++;}};}}});assert.equal(f.app.runtime.mode,'preview');assert.equal(f.app.store.key,f.context.TacticalStore.KEY);assert.equal(mounted,0);f.app.persist({ok:true,persisted:true});f.app.openClassroom();assert.equal(captured,0);assert.equal(f.app.classroom,null);assert.match(f.app.notice(),/不連接正式收件、不代表完成點名/);assert.ok(!f.nodes.get('app').innerHTML.includes('data-action="classroom"'));});
test('formal runtime uses only the formal store key and mounts with the supplied document, host, config and store',()=>{const f=classroomFixture();assert.equal(f.app.runtime.mode,'formal');assert.equal(f.app.storeKey,f.context.TacticalStore.FORMAL_KEY);assert.equal(f.app.store.key,f.context.TacticalStore.FORMAL_KEY);const mount=f.calls.find(c=>c.type==='mount');assert.equal(mount.document,f.document);assert.equal(mount.config.enabled,true);assert.equal(f.api.store,f.app.store);assert.match(f.nodes.get('app').innerHTML,/班級同步/);assert.match(f.app.notice(),/登入並同意後同步至班級/);assert.match(f.app.notice(),/已收件仍待教師核實，不自動算出席/);assert.match(f.app.notice(),/href="\/legacy-v1\/#classroom-receipt"/);});
test('formal and preview profiles and attempts stay separate with no automatic migration',()=>{const preview=fixture();preview.app.start('u03');const previewRaw=preview.values.get(preview.context.TacticalStore.KEY),previewId=preview.app.store.data.profileId;const formal=classroomFixture({values:preview.values});assert.equal(formal.app.store.loadSession().data,null);assert.notEqual(formal.app.store.data.profileId,previewId);formal.app.start('u01');assert.equal(formal.app.store.loadSession().data.missionId,'u01');assert.equal(preview.values.get(preview.context.TacticalStore.KEY),previewRaw);const again=fixture({values:preview.values});assert.equal(again.app.store.loadSession().data.missionId,'u03');assert.equal(again.app.store.data.profileId,previewId);assert.equal(preview.values.size,2);});
test('classroom capture happens only after an explicitly verified persisted success',()=>{const f=classroomFixture();f.calls.length=0;f.app.persist({ok:false,persisted:true,message:'rejected'});f.app.persist({ok:true,persisted:false,message:'memory only'});f.app.persist({ok:true});assert.equal(f.calls.length,0);f.app.persist({ok:true,persisted:true});assert.deepEqual(f.calls.map(c=>c.type),['capture']);});
test('formal menu closes the game dialog before opening the classroom panel and keeps a prominent legacy link',()=>{const f=classroomFixture();f.app.menu();assert.equal(f.nodes.get('game-dialog').open,true);assert.match(f.nodes.get('game-dialog').innerHTML,/data-action="classroom"/);assert.match(f.nodes.get('game-dialog').innerHTML,/href="\/legacy-v1\/"/);assert.match(f.nodes.get('game-dialog').innerHTML,/舊版紀錄／原點名入口/);let wasClosed=false;f.api.openPanel=()=>{wasClosed=!f.nodes.get('game-dialog').open;};f.app.openClassroom();assert.equal(wasClosed,true);});
test('formal result and menu explain conditional sharing without claiming external transmission is disabled or attendance is automatic',()=>{const f=classroomFixture();terminal(f.app);const result=f.app.result();assert.ok(!result.includes('文字不傳送到外部'));assert.ok(!result.includes('新版獨立本機預覽'));assert.match(result,/登入並同意後，反思可同步至班級/);assert.match(result,/已收件仍待教師核實，不自動算出席/);f.app.menu();assert.ok(!f.nodes.get('game-dialog').innerHTML.includes('新版紀錄只留在本機'));assert.match(f.nodes.get('game-dialog').innerHTML,/登入並同意後才同步至班級/);});
test('successful formal import resets consent before any capture of the imported attempt',()=>{const from=classroomFixture(),to=classroomFixture();from.app.start('u01');to.app.start('u03');to.calls.length=0;to.app.pendingImport=from.app.store.exportJSON();to.app.confirmImport();assert.deepEqual(to.calls.map(c=>c.type),['reset','capture']);assert.equal(to.calls[0].reason,'import');assert.equal(to.calls[1].missionId,'u01');assert.equal(to.app.view,'home');});
test('failed import never resets consent or captures a replacement record',()=>{const f=classroomFixture();f.calls.length=0;f.app.pendingImport='{"wrong":true}';f.app.confirmImport();assert.equal(f.calls.length,0);});
test('asynchronous consent reset blocks capture until it resolves and reset failure stays safely blocked',async()=>{const from=classroomFixture(),to=classroomFixture();from.app.start('u01');let resolveReset;to.api.resetConsent=reason=>{to.calls.push({type:'reset',reason});return new Promise(resolve=>{resolveReset=resolve;});};to.calls.length=0;to.app.pendingImport=from.app.store.exportJSON();to.app.confirmImport();assert.equal(to.app.classroomCaptureBlocked,true);assert.deepEqual(to.calls.map(c=>c.type),['reset']);resolveReset();await Promise.resolve();assert.equal(to.app.classroomCaptureBlocked,false);assert.deepEqual(to.calls.map(c=>c.type),['reset','capture']);to.api.resetConsent=()=>{throw Error('storage unavailable');};to.calls.length=0;to.app.pendingImport=from.app.store.exportJSON();to.app.confirmImport();assert.equal(to.app.classroomCaptureBlocked,true);assert.equal(to.calls.length,0);to.app.persist({ok:true,persisted:true});assert.equal(to.calls.length,0);});
test('disabled or failed classroom setup never prevents formal local gameplay or exposes preview data',()=>{let called=0;const f=classroomFixture({classroomConfig:{enabled:false},classroomClient:{mountPublic(){called++;throw Error('must not run');}}});assert.equal(called,0);f.app.start('u03');assert.equal(f.app.state.status,'active');f.app.openClassroom();assert.match(f.nodes.get('game-dialog').innerHTML,/班級同步尚未啟用/);assert.match(f.nodes.get('game-dialog').innerHTML,/舊版紀錄／原點名入口/);const broken=classroomFixture({classroomClient:{mountPublic(){throw Error('unavailable');}}});assert.equal(broken.app.classroom,null);broken.app.start('u03');assert.equal(broken.app.state.status,'active');assert.equal(broken.app.store.key,broken.context.TacticalStore.FORMAL_KEY);});
test('classroom capture errors do not undo a verified local save or interrupt a turn',async()=>{const f=classroomFixture();f.api.capture=()=>{throw Error('network unavailable');};f.app.start('u03');assert.equal(f.app.store.loadSession().data.revision,0);await f.app.execute({type:'skill',unitId:'guardian',skillId:'guard',revision:0});assert.equal(f.app.state.revision,1);assert.equal(f.app.store.loadSession().data.revision,1);assert.equal(f.app.busy,false);assert.match(f.app.classroomError,/班級同步暫時無法更新/);});
test('formal classroom native panel has bounded dimensions, readable consent and 44px controls',()=>{const css=fs.readFileSync('css/tactical.css','utf8');assert.match(css,/\.tactical-classroom-panel\.game-dialog\{[^}]*max-width:800px;max-height:85dvh;overflow:auto/);assert.match(css,/\.tactical-classroom-panel button\{min-height:44px/);assert.match(css,/\.tactical-classroom-panel label\{display:flex;align-items:flex-start/);assert.match(css,/input\[type="checkbox"\][^}]*width:20px;height:20px/);assert.match(css,/\.tactical-classroom-panel \[role="alert"\]/);});

test('the official document and every home/battle brand use the complete approved game name',()=>{assert.match(HTML,/<title>國醫軍事倫理冒險｜晨光行動・回合戰棋<\/title>/);for(const f of [fixture(),classroomFixture()]){assert.match(f.app.header(false),/<span class="brand-name">國醫軍事倫理冒險<\/span>/);assert.match(f.app.header(false),/晨光行動・回合戰棋/);assert.match(f.app.header(false),/aria-label="回到國醫軍事倫理冒險首頁"/);f.app.start('u03');assert.match(f.app.header(true),/<span class="brand-name">國醫軍事倫理冒險<\/span>/);assert.match(f.app.header(true),/<h1>撤離救護站<\/h1>/);}});
test('mobile naming layout keeps the full brand visible and gives chapter names their own row',()=>{const css=fs.readFileSync('css/tactical.css','utf8');assert.ok(!css.includes('.battle-header .brand-title{display:none}'));assert.match(css,/\.brand-name\{display:block;white-space:nowrap\}/);assert.match(css,/grid-template-areas:"brand tools" "mission mission"/);assert.match(css,/@media\(max-width:360px\)/);assert.match(css,/\.battle-header \.brand-title\{display:block;font-size:12px/);});
test('formal notice and menu expose the new privacy policy while preview keeps its existing destinations',()=>{const formal=classroomFixture(),preview=fixture();assert.match(formal.app.notice(),/href="\.\/privacy\.html" target="_blank" rel="noopener noreferrer">紀錄與隱私/);formal.app.menu();assert.match(formal.nodes.get('game-dialog').innerHTML,/formal-record-links/);assert.match(formal.nodes.get('game-dialog').innerHTML,/href="\.\/privacy\.html"/);assert.match(formal.nodes.get('game-dialog').innerHTML,/舊版紀錄／原點名入口/);assert.ok(!preview.app.notice().includes('./privacy.html'));preview.app.menu();assert.ok(!preview.nodes.get('game-dialog').innerHTML.includes('./privacy.html'));assert.ok(!preview.nodes.get('game-dialog').innerHTML.includes('紀錄與隱私'));});
